18	/// Mutable state related to streams, owned by [`Server`] and protected with a mutex.
19	pub struct ServerStreamState<D> {
20	    /// Map from stream ids to stream handles. The stream ids are random integers.
21	    handles: HashMap<u64, Handle<D>>,
22	    /// Queue of streams ordered by the instant when they should expire. All these stream ids
23	    /// should refer to handles in the [`Handle::Available`] variant.
24	    expire_queue: PriorityQueue<u64, Reverse<Instant>>,
25	    /// Queue of expired streams that are still stored as [`Handle::Expired`], together with the
26	    /// instant when we should remove them completely.
27	    cleanup_queue: VecDeque<(u64, Instant)>,
28	    /// The timer that we use to wait for the next item in `expire_queue`.
29	    expire_sleep: Pin<Box<tokio::time::Sleep>>,
30	    /// A waker to wake up the task that expires streams from the `expire_queue`.
31	    expire_waker: Option<task::Waker>,
32	    /// See [`roundup_instant()`].
33	    expire_round_base: Instant,
34	}
35	
36	/// Handle to a stream, owned by the [`ServerStreamState`].
37	#[derive(Debug)]
38	pub(crate) enum Handle<D> {
39	    /// A stream that is open and ready to be used by requests. [`Stream::db`] should always be
40	    /// `Some`.
41	    Available(Box<Stream<D>>),
42	    /// A stream that has been acquired by a request that hasn't finished processing. This will be
43	    /// replaced with `Available` when the request completes and releases the stream.
44	    Acquired,
45	    /// A stream that has been expired. This stream behaves as closed, but we keep this around for
46	    /// some time to provide a nicer error messages (i.e., if the stream is expired, we return a
47	    /// "stream expired" error rather than "invalid baton" error).
48	    Expired,
49	}
50	
51	/// State of a Hrana-over-HTTP stream.
52	///
53	/// The stream is either owned by [`Handle::Available`] (when it's not in use) or by [`Guard`]
54	/// (when it's being used by a request).
55	#[derive(Debug)]
56	pub(crate) struct Stream<D> {
57	    /// The database connection that corresponds to this stream. This is `None` after the `"close"`
58	    /// request was executed.
59	    pub(crate) db: Option<Arc<D>>,
60	    /// The cache of SQL texts stored on the server with `"store_sql"` requests.
61	    sqls: HashMap<i32, String>,
62	    /// Stream id of this stream. The id is generated randomly (it should be unguessable).
63	    stream_id: u64,
64	    /// Sequence number that is expected in the next baton. To make sure that clients issue stream
65	    /// requests sequentially, the baton returned from each HTTP request includes this sequence
66	    /// number, and the following HTTP request must show a baton with the same sequence number.
67	    baton_seq: u64,
68	}
69	
70	/// Guard object that is used to access a stream from the outside. The guard makes sure that the
71	/// stream's entry in [`ServerStreamState::handles`] is either removed or replaced with
72	/// [`Handle::Available`] after the guard goes out of scope.
73	pub struct Guard<'srv, D> {
74	    server: &'srv Server<D>,
75	    /// The guarded stream. This is only set to `None` in the destructor.
76	    stream: Option<Box<Stream<D>>>,
77	    /// If set to `true`, the destructor will release the stream for further use (saving it as
78	    /// [`Handle::Available`] in [`ServerStreamState::handles`]. If false, the stream is removed on
79	    /// drop.
80	    release: bool,
81	}
82	
83	/// An unrecoverable error that should close the stream. The difference from [`ProtocolError`] is
84	/// that a correct client may trigger this error, it does not mean that the protocol has been
85	/// violated.
86	#[derive(thiserror::Error, Debug)]
87	pub enum StreamError {
88	    #[error("The stream has expired due to inactivity")]
89	    StreamExpired,
90	}
