109	/// Acquire a guard to a new or existing stream. If baton is `Some`, we try to look up the stream,
110	/// otherwise we create a new stream.
111	pub async fn acquire<'srv, D: Connection>(
112	    server: &'srv Server<D>,
113	    connection_maker: Arc<dyn MakeConnection<Connection = D>>,
114	    baton: Option<&str>,
115	) -> Result<Guard<'srv, D>> {
116	    let stream = match baton {
117	        Some(baton) => {
118	            let (stream_id, baton_seq) = decode_baton(server, baton)?;
119	
120	            let mut state = server.stream_state.lock();
121	            let handle = state.handles.get_mut(&stream_id);
122	
123	            match handle {
124	                None => {
125	                    return Err(ProtocolError::BatonInvalid)
126	                        .context(format!("Stream handle for {stream_id} was not found"));
127	                }
128	                Some(Handle::Acquired) => {
129	                    return Err(ProtocolError::BatonReused)
130	                        .context(format!("Stream handle for {stream_id} is acquired"));
131	                }
132	                Some(Handle::Expired) => {
133	                    return Err(StreamError::StreamExpired)
134	                        .context(format!("Stream handle for {stream_id} is expired"));
135	                }
136	                Some(Handle::Available(stream)) => {
137	                    if stream.baton_seq != baton_seq {
138	                        return Err(ProtocolError::BatonReused).context(format!(
139	                            "Expected baton seq {}, received {baton_seq}",
140	                            stream.baton_seq
141	                        ));
142	                    }
143	                }
144	            };
145	
146	            let Handle::Available(mut stream) = mem::replace(handle.unwrap(), Handle::Acquired)
147	            else {
148	                unreachable!()
149	            };
150	
151	            tracing::debug!("Stream {stream_id} was acquired with baton seq {baton_seq}");
152	            // incrementing the sequence number forces the next HTTP request to use a different
153	            // baton
154	            stream.baton_seq = stream.baton_seq.wrapping_add(1);
155	            unmark_expire(&mut state, stream.stream_id);
156	            stream
157	        }
158	        None => {
159	            let db = connection_maker.create().await?;
160	
161	            let mut state = server.stream_state.lock();
162	            let stream = Box::new(Stream {
163	                db: Some(Arc::new(db)),
164	                sqls: HashMap::new(),
165	                stream_id: gen_stream_id(&mut state),
166	                // initializing the sequence number randomly makes it much harder to exploit
167	                // collisions in batons
168	                baton_seq: rand::random(),
169	            });
170	            state.handles.insert(stream.stream_id, Handle::Acquired);
171	            tracing::debug!(
172	                "Stream {} was created with baton seq {}",
173	                stream.stream_id,
174	                stream.baton_seq
175	            );
