106	async fn handle_pipeline<C: Connection>(
107	    server: &Server<C>,
108	    connection_maker: Arc<dyn MakeConnection<Connection = C>>,
109	    auth: Authenticated,
110	    req: hyper::Request<hyper::Body>,
111	    version: Version,
112	    encoding: Encoding,
113	) -> Result<hyper::Response<hyper::Body>> {
114	    let req_body: proto::PipelineReqBody = read_decode_request(req, encoding).await?;
115	    let mut stream_guard =
116	        stream::acquire(server, connection_maker, req_body.baton.as_deref()).await?;
117	
118	    let mut results = Vec::with_capacity(req_body.requests.len());
119	    for request in req_body.requests.into_iter() {
120	        tracing::debug!("pipeline:{{ {:?}, {:?} }}", version, request);
121	        let result = request::handle(&mut stream_guard, auth.clone(), request, version).await?;
122	        results.push(result);
123	    }
124	
125	    let resp_body = proto::PipelineRespBody {
126	        baton: stream_guard.release(),
127	        base_url: server.self_url.clone(),
128	        results,
129	    };
130	    Ok(encode_response(hyper::StatusCode::OK, &resp_body, encoding))
131	}
