126	    pub(crate) fn new(stream: HranaStream<T>, sql: String, want_rows: bool) -> crate::Result<Self> {
127	        // in SQLite when a multiple statements are glued together into one string, only the first one is
128	        // executed and then a handle to continue execution is returned. However Hrana API doesn't allow
129	        // passing multi-statement strings, so we just pick first one.
130	        let mut parse = crate::parser::Statement::parse(&sql);
131	        match parse.next() {
132	            None => Err(crate::Error::Misuse(
133	                "no SQL statement provided".to_string(),
134	            )),
135	            Some(Err(e)) => Err(e.into()),
136	            Some(Ok(stmt)) => {
137	                let inner = Stmt::new(stmt.stmt, want_rows);
138	                Ok(Statement { stream, inner })
139	            }
140	        }
141	    }
142	
143	    pub async fn execute(&mut self, params: &Params) -> crate::Result<usize> {
144	        let mut stmt = self.inner.clone();
145	        bind_params(params.clone(), &mut stmt);
146	
147	        let result = self.stream.execute(stmt).await?;
148	        Ok(result.affected_row_count as usize)
149	    }
150	
151	    pub(crate) async fn query_raw(
152	        &mut self,
153	        params: &Params,
154	    ) -> crate::Result<HranaRows<T::Stream>> {
155	        let mut stmt = self.inner.clone();
156	        bind_params(params.clone(), &mut stmt);
157	
158	        let cursor = self.stream.cursor(Batch::single(stmt)).await?;
159	        let rows = HranaRows::from_cursor(cursor).await?;
160	
161	        Ok(rows)
162	    }
163	}
